// HasOwner applies the HasEdge predicate on the "owner" edge.
func HasOwner() predicate.PetAnalysis {
	return predicate.PetAnalysis(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, OwnerTable, OwnerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOwnerWith applies the HasEdge predicate on the "owner" edge with a given conditions (other predicates).
func HasOwnerWith(preds ...predicate.Pet) predicate.PetAnalysis {
	return predicate.PetAnalysis(func(s *sql.Selector) {
		step := newOwnerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PetAnalysis) predicate.PetAnalysis {
	return predicate.PetAnalysis(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PetAnalysis) predicate.PetAnalysis {
	return predicate.PetAnalysis(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PetAnalysis) predicate.PetAnalysis {
	return predicate.PetAnalysis(sql.NotPredicates(p))
}
